1	//! Generic bench driver: the [`Bench`] trait, adaptive outer/inner
2	//! loop sizing, and the band-histogram report.
3	
4	use std::hint::black_box;
5	
6	use hdrhistogram::Histogram;
7	
8	use crate::overhead::Overhead;
9	
10	const WARMUP: u64 = 10_000;
11	const ESTIMATE_STEPS: u64 = 1_000;
12	const ESTIMATE_SAMPLES: usize = 5;
13	const FRAMING_DOMINATION_RATIO: f64 = 10.0;
14	const MAX_INNER: u64 = 1_000;
15	
16	/// A benchmark workload: a named operation that `step()` performs
17	/// in a tight loop for sub-µs latency measurement. Implementors own
18	/// any setup state (channels, spawned threads, counters). `step()`
19	/// returns a value so the caller can `black_box` it against dead-code
20	/// elimination.
21	pub trait Bench {
22	    /// Human-readable name used in the report header.
23	    fn name(&self) -> &str;
24	
25	    /// Run one unit of work. Return any value derived from the work
26	    /// to defeat DCE — the caller black-boxes it.
27	    fn step(&mut self) -> u64;
28	}
29	
30	/// Runtime configuration for one [`run_adaptive`] call.
31	#[derive(Debug)]
32	pub struct RunCfg<'a> {
33	    /// Calibrated apparatus overhead (framing + loop/iter) used to
34	    /// compute the `adjusted` mean columns in the report.
35	    pub overhead: &'a Overhead,
36	    /// Wall-clock seconds budget for time-based runs. Ignored when
37	    /// `outer_override` is set.
38	    pub target_seconds: f64,
39	    /// Force a fixed outer-loop count, bypassing the time budget.
40	    pub outer_override: Option<u64>,
41	    /// Force a fixed inner-loop count, bypassing the
42	    /// overhead-dominated auto-sizing.
43	    pub inner_override: Option<u64>,
44	    /// Core pool for thread pinning. Indexed positionally with
45	    /// wrap-around via [`core_for`][RunCfg::core_for]; empty means
46	    /// no pinning.
47	    pub pin_cores: &'a [usize],
48	}
49	
50	impl RunCfg<'_> {
51	    /// CPU id for the bench's `thread_idx`-th thread, using
52	    /// wrap-around over the pool. Returns `None` when the pool is
53	    /// empty so callers can treat unpinned and pinned runs uniformly.
54	    pub fn core_for(&self, thread_idx: usize) -> Option<usize> {
55	        if self.pin_cores.is_empty() {
56	            None
57	        } else {
58	            Some(self.pin_cores[thread_idx % self.pin_cores.len()])
59	        }
60	    }
61	}
62	
63	/// Drive `bench` against `cfg` and return
64	/// `(histogram, outer, inner, duration_s)`.
65	///
66	/// After a fixed warmup, `inner` is auto-sized so apparatus framing
67	/// doesn't dominate (skipped when `cfg.inner_override` is set). The
68	/// outer loop runs either for `cfg.outer_override` iterations or
69	/// until `cfg.target_seconds` elapses.
70	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> (Histogram<u64>, u64, u64, f64) {
71	    for _ in 0..WARMUP {
72	        black_box(bench.step());
73	    }
74	
75	    let step_cost_ns = estimate_step_cost(bench);
76	    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
77	    let inner = cfg
78	        .inner_override
79	        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
80	
81	    match cfg.outer_override {
82	        Some(outer) => {
83	            let (hist, duration_s) = run_counted(bench, outer, inner);
84	            (hist, outer, inner, duration_s)
85	        }
86	        None => {
87	            let (hist, duration_s) = run_timed(bench, cfg.target_seconds, inner);
88	            let outer = hist.len();
89	            (hist, outer, inner, duration_s)
90	        }
91	    }
92	}
93	
94	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
95	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
96	        .map(|_| {
97	            let start = minstant::Instant::now();
98	            for _ in 0..ESTIMATE_STEPS {
99	                black_box(bench.step());
100	            }
101	            let total = start.elapsed().as_nanos() as u64;
102	            total as f64 / ESTIMATE_STEPS as f64
103	        })
104	        .collect();
105	    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
106	    samples[ESTIMATE_SAMPLES / 2]
107	}
108	
109	fn pick_inner(step_cost_ns: f64, framing_ns: f64) -> u64 {
110	    let target = (FRAMING_DOMINATION_RATIO * framing_ns / step_cost_ns).ceil() as u64;
111	    target.clamp(1, MAX_INNER)
112	}
113	
114	fn run_counted<B: Bench>(bench: &mut B, outer: u64, inner: u64) -> (Histogram<u64>, f64) {
115	    let mut hist = new_hist();
116	    let run_start = minstant::Instant::now();
117	    for _ in 0..outer {
118	        record_sample(bench, inner, &mut hist);
119	    }
120	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
121	    (hist, duration_s)
122	}
123	
124	fn run_timed<B: Bench>(bench: &mut B, target_seconds: f64, inner: u64) -> (Histogram<u64>, f64) {
125	    let mut hist = new_hist();
126	    let target_ns = (target_seconds * 1e9) as u128;
127	    let run_start = minstant::Instant::now();
128	    loop {
129	        record_sample(bench, inner, &mut hist);
130	        if run_start.elapsed().as_nanos() >= target_ns {
131	            break;
132	        }
133	    }
134	    let duration_s = run_start.elapsed().as_nanos() as f64 / 1e9;
135	    (hist, duration_s)
136	}
137	
138	fn new_hist() -> Histogram<u64> {
139	    // 1 ns to 60 s, 3 sig figs
140	    Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap()
141	}
142	
143	fn record_sample<B: Bench>(bench: &mut B, inner: u64, hist: &mut Histogram<u64>) {
144	    let start = minstant::Instant::now();
145	    for _ in 0..inner {
146	        black_box(bench.step());
147	    }
148	    let elapsed_ns = start.elapsed().as_nanos() as u64;
149	    hist.record(round_elapsed(elapsed_ns, inner)).unwrap();
150	}
151	
152	fn round_elapsed(elapsed_ns: u64, inner: u64) -> u64 {
153	    (elapsed_ns + inner / 2) / inner
154	}
155	
156	/// Format an integer with thousands separators, e.g.
157	/// `12345` → `"12,345"`.
158	pub fn fmt_commas(n: u64) -> String {
159	    let s = n.to_string();
160	    let mut result = String::new();
161	    for (i, c) in s.chars().rev().enumerate() {
162	        if i > 0 && i % 3 == 0 {
163	            result.push(',');
164	        }
165	        result.push(c);
166	    }
167	    result.chars().rev().collect()
168	}
169	
170	/// Format a float with `decimals` fractional digits and thousands
171	/// separators on the integer part.
172	pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
173	    let s = format!("{n:.decimals$}");
174	    let (sign, body) = match s.strip_prefix('-') {
175	        Some(rest) => ("-", rest),
176	        None => ("", s.as_str()),
177	    };
178	    let (int_part, frac_part) = match body.find('.') {
179	        Some(i) => (&body[..i], &body[i..]),
180	        None => (body, ""),
181	    };
182	    let int_num: u64 = int_part.parse().unwrap_or(0);
183	    format!("{sign}{}{frac_part}", fmt_commas(int_num))
184	}
185	
186	/// Print the full bench report: header line (logfmt-style metadata),
187	/// per-band histogram (min→p1, p1→p10, … p99→max), whole-histogram
188	/// mean/stdev, and trimmed mean/stdev (min–p99, excluding the p99→max
189	/// tail). The `adjusted` columns subtract per-call apparatus overhead
190	/// (`overhead.per_call_ns(inner)`); the untrimmed `stdev` is the
191	/// hdrhistogram-native stdev, which includes the ms-scale outliers
192	/// in the tail band.
193	pub fn print_report(
194	    name: &str,
195	    outer: u64,
196	    inner: u64,
197	    duration_s: f64,
198	    hist: &Histogram<u64>,
199	    overhead: &Overhead,
200	) {
201	    // Header line: bench name + logfmt-style metadata. `adj` is the
202	    // apparatus overhead subtracted from each sample downstream.
203	    let adj = overhead.per_call_ns(inner);
204	    let total = outer * inner;
205	    println!(
206	        "{name} [duration={:.1}s outer={} inner={} calls={} adj/call={}ns]:",
207	        duration_s,
208	        fmt_commas(outer),
209	        inner,
210	        fmt_commas(total),
211	        fmt_commas_f64(adj, 2),
212	    );
213	
214	    // Band boundaries defined by percentiles. Each consecutive pair
215	    // forms one band; we iterate the histogram to compute per-band
216	    // stats (first, last, count, mean).
217	    let boundary_pcts: &[f64] = &[
218	        0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
219	    ];
220	    let boundary_names: &[&str] = &[
221	        "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
222	    ];
223	
224	    let n_bands = boundary_pcts.len() - 1;
225	    let sample_count = hist.len();
226	
227	    // Accumulate per-band stats by walking recorded histogram buckets.
228	    // Each bucket is assigned to the band containing its midpoint rank.
229	    let mut band_first = vec![u64::MAX; n_bands];
230	    let mut band_last = vec![0u64; n_bands];
231	    let mut band_count = vec![0u64; n_bands];
232	    let mut band_sum = vec![0u128; n_bands];
233	
234	    let mut cumulative = 0u64;
235	    for iv in hist.iter_recorded() {
236	        let value = iv.value_iterated_to();
237	        let count = iv.count_at_value();
238	        let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
239	        let idx = boundary_pcts[1..]
240	            .iter()
241	            .position(|&b| mid_rank < b)
242	            .unwrap_or(n_bands - 1);
243	        band_first[idx] = band_first[idx].min(value);
244	        band_last[idx] = band_last[idx].max(value);
245	        band_count[idx] += count;
246	        band_sum[idx] += value as u128 * count as u128;
247	        cumulative += count;
248	    }
249	
250	    // Build rendered rows: (label, first, last, range, count, mean, adj_mean).
251	    struct BandRow {
252	        label: String,
253	        first: String,
254	        last: String,
255	        range: String,
256	        count: String,
257	        mean: String,
258	        adj_mean: String,
259	    }
260	
261	    let mut rows: Vec<BandRow> = Vec::new();
262	    for i in 0..n_bands {
263	        if band_count[i] == 0 {
264	            continue;
265	        }
266	        let mean_val = band_sum[i] as f64 / band_count[i] as f64;
267	        let adj_mean = (mean_val - adj).max(0.0);
268	        rows.push(BandRow {
269	            label: format!("{}-{}", boundary_names[i], boundary_names[i + 1]),
270	            first: fmt_commas(band_first[i]),
271	            last: fmt_commas(band_last[i]),
272	            range: fmt_commas(band_last[i] - band_first[i] + 1),
273	            count: fmt_commas(band_count[i]),
274	            mean: fmt_commas_f64(mean_val, 0),
275	            adj_mean: fmt_commas_f64(adj_mean, 0),
276	        });
277	    }
278	
279	    // Column widths from rendered strings.
280	    let label_w = rows
281	        .iter()
282	        .map(|r| r.label.len())
283	        .max()
284	        .unwrap_or(0)
285	        .max("stdev min-p99".len());
286	    let first_w = rows.iter().map(|r| r.first.len()).max().unwrap_or(0);
287	    let last_w = rows.iter().map(|r| r.last.len()).max().unwrap_or(0);
288	    let range_w = rows.iter().map(|r| r.range.len()).max().unwrap_or(0);
289	    let count_w = rows.iter().map(|r| r.count.len()).max().unwrap_or(0);
290	    let mean_w = rows.iter().map(|r| r.mean.len()).max().unwrap_or(0);
291	    let adj_w = rows.iter().map(|r| r.adj_mean.len()).max().unwrap_or(0);
292	
293	    const INDENT: &str = "  ";
294	    const GAP: &str = "    ";
295	
296	    // Header row.
297	    let first_col = INDENT.len() + label_w + 1 + first_w;
298	    let last_gap = " ns".len() + GAP.len() + last_w;
299	    let range_gap = " ns".len() + GAP.len() + range_w;
300	    let count_gap = " ns".len() + GAP.len() + count_w;
301	    let mean_gap = GAP.len() + mean_w;
302	    let adj_gap = " ns".len() + GAP.len() + adj_w;
303	    println!(
304	        "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}{:>adj_gap$}",
305	        "first", "last", "range", "count", "mean", "adjusted",
306	    );
307	
308	    for r in &rows {
309	        println!(
310	            "{INDENT}{:<label_w$} {:>first_w$} ns{GAP}{:>last_w$} ns{GAP}{:>range_w$} ns{GAP}{:>count_w$}{GAP}{:>mean_w$} ns{GAP}{:>adj_w$} ns",
311	            r.label, r.first, r.last, r.range, r.count, r.mean, r.adj_mean,
312	        );
313	    }
314	
315	    // Whole-histogram summary. Aligned to mean/adjusted columns.
316	    let hist_mean = hist.mean();
317	    let hist_adj = (hist_mean - adj).max(0.0);
318	    let skip = first_w
319	        + " ns".len()
320	        + GAP.len()
321	        + last_w
322	        + " ns".len()
323	        + GAP.len()
324	        + range_w
325	        + " ns".len()
326	        + GAP.len()
327	        + count_w;
328	    println!(
329	        "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns{GAP}{:>adj_w$} ns",
330	        "mean",
331	        "",
332	        fmt_commas_f64(hist_mean, 0),
333	        fmt_commas_f64(hist_adj, 0),
334	    );
335	    println!(
336	        "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
